export default function driveNotionProgress({
  files,
  dataSourceId,
  titleKey,
  previousState,
  page,
}) {
  if (
    !Array.isArray(files) ||
    typeof dataSourceId !== "string" ||
    !dataSourceId ||
    typeof titleKey !== "string" ||
    !titleKey
  )
    throw new Error("Expected files and a checked Notion schema");
  let state;
  if (previousState == null) state = { index: 0, receipts: [] };
  else {
    if (
      !Number.isInteger(previousState.index) ||
      previousState.index < 1 ||
      previousState.index > files.length ||
      !Array.isArray(previousState.receipts) ||
      previousState.receipts.length !== previousState.index - 1
    )
      throw new Error("Invalid Notion page progress");
    if (
      !page ||
      page.object !== "page" ||
      typeof page.id !== "string" ||
      !page.id ||
      page.parent?.data_source_id !== dataSourceId
    )
      throw new Error(
        "Notion did not confirm the page in the selected data source; creation may already have occurred",
      );
    state = {
      index: previousState.index,
      receipts: [
        ...previousState.receipts,
        { fileId: files[previousState.index - 1].fileId, page },
      ],
    };
  }
  const file = files[state.index];
  const parent = { type: "data_source_id", data_source_id: dataSourceId };
  if (file == null)
    return { state, more: false, parent, properties: {}, count: state.receipts.length };
  const properties = {
    File: { files: [{ name: file.name, type: "external", external: { url: file.webViewLink } }] },
  };
  if (file.name !== "")
    properties[titleKey] = { title: [{ type: "text", text: { content: file.name } }] };
  return {
    state: { index: state.index + 1, receipts: state.receipts },
    more: true,
    parent,
    properties,
    count: state.receipts.length,
  };
}
